def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        """Calculate the sum of proper divisors of n."""
        divisors_sum = 1  # 1 is always a divisor
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                divisors_sum += i
                if i != n // i:
                    divisors_sum += n // i
        return divisors_sum

    amicable_sum = 0
    for a in range(2, limit + 1):
        b = sum_of_divisors(a)
        if b != a and b <= limit and sum_of_divisors(b) == a:
            amicable_sum += a
    return amicable_sum
```

