def count_Primes_nums(n):
    if n <= 2:
        return 0

    # Create a boolean array "is_prime[0..n-1]" and initialize all entries as True
    # A value in is_prime[i] will be False if i is not a prime, else True
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not primes

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            # Mark multiples of i as not prime
            for multiple in range(i * i, n, i):
                is_prime[multiple] = False

    # Count the number of True values in is_prime, which correspond to prime numbers
    return sum(is_prime)
```

