def find_kth(arr1, arr2, k):
    def kth_helper(arr1, arr2, k):
        # Base cases
        if not arr1:
            return arr2[k - 1]
        if not arr2:
            return arr1[k - 1]
        if k == 1:
            return min(arr1[0], arr2[0])

        # Divide and conquer
        mid1 = arr1[k // 2 - 1] if len(arr1) >= k // 2 else float('inf')
        mid2 = arr2[k // 2 - 1] if len(arr2) >= k // 2 else float('inf')

        if mid1 < mid2:
            return kth_helper(arr1[k // 2:], arr2, k - k // 2)
        else:
            return kth_helper(arr1, arr2[k // 2:], k - k // 2)

    return kth_helper(arr1, arr2, k)

# Example usage:
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
```

