def count_Substrings(s: str) -> int:
    def sum_of_digits(substring: str) -> int:
        return sum(int(char) for char in substring)

    count = 0
    n = len(s)

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += int(s[j])
            if current_sum == (j - i + 1):  # Sum of digits equals substring length
                count += 1

    return count

