def tuple_modulo(tuple1, tuple2):
    if len(tuple1) != len(tuple2):
        raise ValueError("Both tuples must have the same length")
    return tuple(a % b for a, b in zip(tuple1, tuple2))

# Example usage:
assert tuple_modulo((10, 4, 5, 6), (5, 6, 7, 5)) == (0, 4, 5, 1)
```

